Add-Type -AssemblyName System.Drawing
$dir='audit/massing_phi_delta_theta_258cddd/sources'; $bmp=[System.Drawing.Bitmap]::new(1024,512); $g=[System.Drawing.Graphics]::FromImage($bmp)
foreach($xx in 271135..271138){foreach($yy in 395351..395352){$p=Join-Path $dir ("esri_world_imagery_z20_{0}_{1}.jpg" -f $xx,$yy); $im=[System.Drawing.Image]::FromFile((Resolve-Path $p)); $g.DrawImage($im,($xx-271135)*256,($yy-395351)*256,256,256); $im.Dispose()}}
$src=Get-Content (Join-Path $dir 'purdue_gis_fid_796_current.json') -Raw | ConvertFrom-Json; $ring=$src.features[0].geometry.rings[0]; $n=[math]::Pow(2,20); $pts=[System.Collections.Generic.List[System.Drawing.PointF]]::new(); foreach($pt in $ring){$lon=$pt[0];$lat=$pt[1];$px=(($lon+180)/360*$n*256)-271135*256;$latr=$lat*[math]::PI/180;$py=((1-[math]::Log([math]::Tan($latr)+1/[math]::Cos($latr))/[math]::PI)/2*$n*256)-395351*256;$pts.Add([System.Drawing.PointF]::new([single]$px,[single]$py))}; $pen=[System.Drawing.Pen]::new([System.Drawing.Color]::Yellow,2.5);$g.DrawPolygon($pen,$pts.ToArray()); $out='audit/massing_phi_delta_theta_258cddd/renders/gis_footprint_imagery_overlay.png';$bmp.Save($out,[System.Drawing.Imaging.ImageFormat]::Png);$pen.Dispose();$g.Dispose();$bmp.Dispose();Get-Item $out | Select Name,Length
